     * Checks a typed answer. Unknown ids are `Different`.
     */
    func checkAnswer(phraseId: String, typed: String)  -> Verdict
    
    /**
     * Checks a typed answer against one sentence: a pattern's example.
     */
    func checkSentence(sentence: String, typed: String)  -> Verdict
    
    /**
     * The runtime's event stream: `Changed { revision }` after each
     * committed command, phase changes, and drops. Nil after shutdown.
     */
    func events()  -> RuntimeEvents?
    
    /**
     * The home screen. `day_start_ms` is when today began on the phone's
     * clock (Swift knows the time zone).
     */
    func home(dayStartMs: Int64)  -> Home
    
    /**
     * What the runtime found at open (unfinished background work).
     */
    func launchReport()  -> LaunchReport
    
    /**
     * A listening round of `count` phrases.
     */
    func listening(count: UInt32, seed: UInt64)  -> [ListeningItem]
    
    /**
     * The phase last reported.
     */
    func phase()  -> AppPhase
    
    func phrase(id: String)  -> PhraseView?
    
    /**
     * Phrases in a topic (every topic when None) matching `query` (all
     * when empty).
     */
    func phrases(topic: String?, query: String)  -> [PhraseView]
    
    /**
     * Records an attempt at a skill, and returns the phrase as it is now.
     */
    func record(phraseId: String, skill: Skill, outcome: Outcome, latencyMs: UInt32?) async throws  -> PhraseView
    
    /**
     * Up to `limit` phrases due again.
     */
    func review(limit: UInt32)  -> [ReviewItem]
    
    /**
     * The last committed revision.
     */
    func revision()  -> UInt64
    
    func scenario(id: String)  -> ScenarioView?
    
    /**
     * Records that phrases were shown (a card, a conversation).
     */
    func seen(phraseIds: [String]) async throws 
    
    func setEnglish(english: EnglishSupport) async throws 
    
    func setName(name: String) async throws 
    
    /**
     * The host reports the application lifecycle phase.
     */
    func setPhase(phase: AppPhase) 
    
    func settings()  -> Settings
    
    /**
     * Refuses new commands, stops work in flight and ends event
     * streams. Commands already accepted still finish and save.
     */
    func shutdown() 
    
    /**
     * Forgets all progress and attempts (keeps the settings).
     */
    func startOver() async throws 
    
    func topics()  -> [TopicView]
    
    func totals(dayStartMs: Int64)  -> Totals
    
}
